meta.acceptance:
D=/tmp/morph/read-registry-p4; mkdir -p $D; S=$(date +%s)-$$; L=$D/acc-$S.log
cp src/processor/types.ts $D/0-$S.ts 2>/dev/null
cp src/processor/registry.ts $D/1-$S.ts 2>/dev/null
(
 set -e
 export NO_COLOR=1 CI=1
P=$PWD/probe/read-registry; rm -rf $P; mkdir -p $P; trap 'rm -rf $P' EXIT
cat > $P/guard.mjs <<'MORPH_GUARD_EOF'
// MorphV2 guard: the layer rules of docs/CONVENTIONS.md and the test-file rules, checked on
// the TypeScript syntax tree. Inlined into every acceptance by decks/tools/build.py.
//   node guard.mjs src [file,file,...]                   every .ts under src/, or only these
//   node guard.mjs helpers <file> <name,name,...>        the stub module: node:* only, exports
//   node guard.mjs tests <file> <min> <max> [lits.json]  one test file; lits = strings it must hold
import ts from "typescript";
import fs from "node:fs";
import path from "node:path";

const bad = [];

// which internal layers a layer may import; "*" = any; unknown dirs are reported
const LAYERS = {
  cards: [], wait: [],
  response: ["cards"], store: ["cards"], compiler: ["cards"], language: ["cards"],
  contour: ["cards"], git: ["cards"], acceptance: ["cards", "wait", "compiler"],
  processor: ["cards", "wait", "compiler"], planner: ["cards", "contour", "language"],
  primer: ["cards", "git", "store", "language"],
  scout: ["cards", "processor", "wait", "primer"],
  reviewer: ["cards", "contour", "primer", "scout", "git"],
  runloop: ["cards", "wait", "store", "compiler", "response", "acceptance", "language",
    "git", "processor"],
  cli: "*",
};
const ROOT_FILES = new Set(["src/index.ts"]);
const SHELL = new Set(["acceptance", "git"]);          // node:child_process
const NET = new Set(["processor"]);                    // fetch, WebSocket, XMLHttpRequest
const CONSOLE = new Set(["cli"]);                      // console, process.exit
const PROCESS = new Set(["cli", "processor", "acceptance", "git"]);
const NO_CLOCK = new Set(["cards", "compiler", "response", "language", "contour", "planner"]);
const YAML = new Set(["contour"]);
// P3: the acceptance gets the child's environment as a parameter (docs/TASK_P3_acceptance.md §4)
const NO_ENV = new Set(["acceptance", "processor"]);
// P4: the one file of a NO_ENV layer that may read process.env (Read Registry, docs/TASK_P4_processor.md §4)
const ENV_READERS = new Set(["src/processor/registry.ts"]);

function parse(file) {
  return ts.createSourceFile(file, fs.readFileSync(file, "utf8"), ts.ScriptTarget.Latest, true,
    ts.ScriptKind.TS);
}
function line(sf, node) {
  return sf.getLineAndCharacterOfPosition(node.getStart(sf)).line + 1;
}
function report(sf, node, rule) {
  bad.push(`guard: ${sf.fileName}:${line(sf, node)} ${rule}`);
}
function walk(node, fn) {
  fn(node);
  ts.forEachChild(node, (child) => walk(child, fn));
}
// an identifier that refers to a value binding (not a property name, a type, a declared name)
function isValueRef(node) {
  const p = node.parent;
  if (!p) return false;
  if (ts.isPropertyAccessExpression(p) && p.name === node) return false;
  if ((ts.isPropertyAssignment(p) || ts.isPropertyDeclaration(p) || ts.isPropertySignature(p) ||
       ts.isMethodDeclaration(p) || ts.isMethodSignature(p) || ts.isGetAccessor(p) ||
       ts.isSetAccessor(p) || ts.isEnumMember(p)) && p.name === node) return false;
  if (ts.isTypeReferenceNode(p) || ts.isQualifiedName(p) || ts.isTypeQueryNode(p)) return false;
  if ((ts.isParameter(p) || ts.isVariableDeclaration(p) || ts.isFunctionDeclaration(p) ||
       ts.isBindingElement(p)) && p.name === node) return false;
  if (ts.isImportSpecifier(p) || ts.isExportSpecifier(p) || ts.isImportClause(p)) return false;
  if (ts.isLabeledStatement(p) || ts.isBreakOrContinueStatement(p)) return false;
  return true;
}
function tsFiles(dir) {
  const out = [];
  if (!fs.existsSync(dir)) return out;
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const f = path.join(dir, e.name);
    if (e.isDirectory()) out.push(...tsFiles(f));
    else if (f.endsWith(".ts")) out.push(f);
  }
  return out.sort();
}
function moduleSpecifiers(sf) {
  const out = [];
  walk(sf, (node) => {
    if ((ts.isImportDeclaration(node) || (ts.isExportDeclaration(node) && node.moduleSpecifier)) &&
        ts.isStringLiteralLike(node.moduleSpecifier)) out.push([node, node.moduleSpecifier.text]);
    if (ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword)
      report(sf, node, "dynamic import");
  });
  return out;
}
function layerOf(rel) {
  const parts = rel.split("/");
  return parts.length >= 3 && parts[0] === "src" ? parts[1] : null;
}

function checkSrc(files) {
  for (const file of files ?? tsFiles("src")) {
    const sf = parse(file);
    const rel = file.split(path.sep).join("/");
    const layer = layerOf(rel);
    if (layer === null && !ROOT_FILES.has(rel)) { bad.push(`guard: ${rel} is not under a layer directory`); continue; }
    if (layer !== null && !(layer in LAYERS)) { bad.push(`guard: ${rel} is in an unknown layer "${layer}"`); continue; }
    const allowed = layer === null ? [] : LAYERS[layer];
    for (const [node, spec] of moduleSpecifiers(sf)) {
      if (spec.startsWith("node:")) {
        if (spec === "node:child_process" && !SHELL.has(layer))
          report(sf, node, `node:child_process outside src/acceptance and src/git`);
        continue;
      }
      if (spec === "yaml") { if (!YAML.has(layer)) report(sf, node, `"yaml" outside src/contour`); continue; }
      if (!spec.startsWith("./") && !spec.startsWith("../")) { report(sf, node, `package import "${spec}" (node:* only)`); continue; }
      const target = path.posix.normalize(path.posix.join(path.posix.dirname(rel), spec));
      const tl = layerOf(target);
      if (tl === null) { if (!ROOT_FILES.has(target)) report(sf, node, `import of "${spec}" outside src/<layer>/`); continue; }
      if (tl !== layer && allowed !== "*" && !allowed.includes(tl))
        report(sf, node, `layer ${layer ?? "src"} imports layer ${tl} (allowed: ${allowed.join(", ") || "none"})`);
    }
    walk(sf, (node) => {
      if (node.kind === ts.SyntaxKind.AnyKeyword) report(sf, node, "explicit any");
      if (ts.isIdentifier(node) && isValueRef(node)) {
        const n = node.text;
        if (["fetch", "WebSocket", "XMLHttpRequest"].includes(n) && !NET.has(layer))
          report(sf, node, `global ${n} outside src/processor`);
        if (n === "console" && !CONSOLE.has(layer)) report(sf, node, "console outside src/cli");
        if (n === "process" && !PROCESS.has(layer)) report(sf, node, "process outside src/cli, src/processor, src/acceptance, src/git");
        if (n === "Date" && NO_CLOCK.has(layer)) report(sf, node, `Date in the deterministic layer ${layer}`);
        if (n === "Math" && node.parent && ts.isPropertyAccessExpression(node.parent) &&
            node.parent.name.text === "random") report(sf, node, "Math.random");
      }
      if (ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression) &&
          node.expression.text === "process" && node.name.text === "exit" && !CONSOLE.has(layer))
        report(sf, node, "process.exit outside src/cli");
      if (ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression) &&
          node.expression.text === "process" && node.name.text === "env" && NO_ENV.has(layer) &&
          !ENV_READERS.has(rel))
        report(sf, node, `process.env in src/${layer} (the environment is a parameter)`);
    });
  }
}

function checkHelpers(file, names) {
  if (!fs.existsSync(file)) { bad.push(`guard: ${file} missing`); return; }
  const sf = parse(file);
  for (const [node, spec] of moduleSpecifiers(sf))
    if (!spec.startsWith("node:")) report(sf, node, `helpers import "${spec}" (node:* only)`);
  const exported = new Set();
  walk(sf, (node) => {
    if (node.kind === ts.SyntaxKind.AnyKeyword) report(sf, node, "explicit any");
    const mods = ts.canHaveModifiers(node) ? ts.getModifiers(node) ?? [] : [];
    if (!mods.some((m) => m.kind === ts.SyntaxKind.ExportKeyword)) return;
    if ((ts.isFunctionDeclaration(node) || ts.isInterfaceDeclaration(node) ||
         ts.isTypeAliasDeclaration(node) || ts.isClassDeclaration(node)) && node.name)
      exported.add(node.name.text);
    if (ts.isVariableStatement(node))
      for (const d of node.declarationList.declarations) if (ts.isIdentifier(d.name)) exported.add(d.name.text);
  });
  for (const n of names) if (!exported.has(n)) bad.push(`guard: ${file} does not export ${n}`);
}

function checkTest(file, min, max, lits) {
  if (!fs.existsSync(file)) { bad.push(`guard: ${file} missing`); return; }
  const sf = parse(file);
  const text = sf.getFullText();
  let count = 0;
  for (const [node, spec] of moduleSpecifiers(sf))
    if (spec !== "vitest" && !spec.startsWith("node:") && !spec.startsWith("./") && !spec.startsWith("../"))
      report(sf, node, `import of a package "${spec}" (vitest, node:* and relative paths only)`);
  walk(sf, (node) => {
    if (node.kind === ts.SyntaxKind.AnyKeyword) report(sf, node, "explicit any");
    if (ts.isCallExpression(node) && ts.isIdentifier(node.expression) &&
        (node.expression.text === "test" || node.expression.text === "it")) count += 1;
    if (ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression)) {
      const o = node.expression.text, p = node.name.text;
      if (["test", "it", "describe"].includes(o) && ["skip", "only", "todo", "fails"].includes(p))
        report(sf, node, `${o}.${p}`);
      if (o === "vi" && ["stubGlobal", "useFakeTimers", "mock", "doMock"].includes(p))
        report(sf, node, `vi.${p} (stubs come from tests/helpers.ts)`);
    }
    if (ts.isIdentifier(node) && isValueRef(node) &&
        ["setTimeout", "setInterval", "setImmediate"].includes(node.text))
      report(sf, node, `${node.text} (real timers are not used under tests/; use fakeClock)`);
    const declared = (ts.isFunctionDeclaration(node) || ts.isVariableDeclaration(node) ||
      ts.isClassDeclaration(node)) && node.name && ts.isIdentifier(node.name) ? node.name.text : null;
    if (declared && (declared === "fetch" || /^[Ff]ake/.test(declared)))
      report(sf, node, `own stub "${declared}" (stubs come from tests/helpers.ts)`);
  });
  if (count < min || count > max)
    bad.push(`guard: ${file} has ${count} test/it calls, expected ${min}..${max}`);
  for (const lit of lits) if (!text.includes(lit)) bad.push(`guard: ${file} does not mention the example literal ${JSON.stringify(lit)}`);
}

const [mode, a, b, c, d] = process.argv.slice(2);
if (mode === "src") checkSrc(a ? a.split(",").filter(Boolean) : null);
else if (mode === "helpers") checkHelpers(a, (b ?? "").split(",").filter(Boolean));
else if (mode === "tests") checkTest(a, Number(b), Number(c), d ? JSON.parse(fs.readFileSync(d, "utf8")) : []);
else bad.push(`guard: unknown mode ${mode}`);
for (const x of bad) console.log(x);
process.exit(bad.length ? 1 : 0);
MORPH_GUARD_EOF
cat > $P/probe.config.mts <<'MORPH_CONF_EOF'
import { defineConfig } from "vitest/config";
import { fileURLToPath } from "node:url";
export default defineConfig({
  root: fileURLToPath(new URL("../..", import.meta.url)),
  test: { environment: "node", include: ["probe/read-registry/**/*.probe.ts"],
    setupFiles: ["tests/setup.ts"], chaiConfig: { truncateThreshold: 200 } },
});
MORPH_CONF_EOF
cat > $P/tsconfig.card.json <<'MORPH_TSCONF_EOF'
{
  "extends": "../../tsconfig.json",
  "include": [
    "../../src",
    "../../tests",
    "./*.probe.ts"
  ]
}
MORPH_TSCONF_EOF
cat > $P/read-registry.probe.ts <<'MORPH_PROBE_EOF'
// P4 probe for read-registry: readRegistry by docs/TASK_P4_processor.md §2.2, one test per
// record example (Component processor, Function Read Registry), then every boundary row of
// the §2.2 table. Values and types; null is checked as null, never through `??`.
import { test, expect } from "vitest";
import { DEFAULT_BASE_URL, KEYS, PREFIX, readRegistry } from "../../src/processor/registry.js";
import type { ProcessorConfig, Registry } from "../../src/processor/types.js";
import type { Fault } from "../../src/cards/types.js";
import { fixtureJson } from "../../tests/helpers.js";

const lines = (fs: Fault[]): string => fs.map((f) => `${f.key} | ${f.message}`).join("\n");
const ids = (r: Registry): string => r.configs.map((c) => c.id).join(",");

test("Read Registry example 1: the glm53 processor, PATH ignored", () => {
  const got: Registry = readRegistry({
    PATH: "/usr/bin:/bin",
    MORPH_PROCESSOR_glm53_TYPE: "openrouter",
    MORPH_PROCESSOR_glm53_MODEL: "z-ai/glm-5.3",
    MORPH_PROCESSOR_glm53_API_KEY: "sk-or-test",
    MORPH_PROCESSOR_glm53_CONCURRENCY: "4",
    MORPH_PROCESSOR_glm53_PROVIDER_ORDER: "Novita, Together",
    MORPH_PROCESSOR_glm53_REASONING_MAX_TOKENS: "2500",
  });
  expect(lines(got.faults), "faults").toBe("");
  expect(got.configs.length, "one config").toBe(1);
  const want = fixtureJson("processor/glmConfig.json") as ProcessorConfig;
  const c: ProcessorConfig = got.configs[0] as ProcessorConfig;
  expect(c, "the config of processor/glmConfig.json").toStrictEqual(want);
  expect(`${PREFIX} ${DEFAULT_BASE_URL} ${KEYS.length}`, "the constants").toBe(
    "MORPH_PROCESSOR_ https://openrouter.ai/api/v1 12");
});

test("Read Registry example 2: a stub with every default, the value trimmed", () => {
  const got = readRegistry({ MORPH_PROCESSOR_stub_TYPE: "stub", MORPH_PROCESSOR_stub_ANSWERS_DIR: " /tmp/answers " });
  expect(lines(got.faults), "faults").toBe("");
  expect(got.configs.length, "one config").toBe(1);
  const want: ProcessorConfig = {
    id: "stub", type: "stub", model: "stub", apiKey: null, baseUrl: "https://openrouter.ai/api/v1", route: "sync",
    concurrency: 1, providerOrder: null, reasoning: null, timeoutMs: 600000, maxRetries: 2, answersDir: "/tmp/answers",
  };
  expect(got.configs[0], "the stub config").toStrictEqual(want);
  expect(got.configs[0]?.apiKey === null, "apiKey is null (not undefined, not '')").toBe(true);
  expect(got.configs[0]?.providerOrder === null, "providerOrder is null").toBe(true);
});

test("Read Registry example 3: invalid processors are listed as faults, sorted by key", () => {
  const got = readRegistry({
    MORPH_PROCESSOR_a_TYPE: "openrouter",
    MORPH_PROCESSOR_b_TYPE: "stub", MORPH_PROCESSOR_b_ANSWERS_DIR: "/x", MORPH_PROCESSOR_b_CONCURRENCY: "0",
    MORPH_PROCESSOR_c_TYPE: "openai",
    MORPH_PROCESSOR_d_TYPE: "stub", MORPH_PROCESSOR_d_ANSWERS_DIR: "/x",
  });
  expect(ids(got), "only d is configured").toBe("d");
  expect(lines(got.faults), "four faults in key order").toBe([
    "MORPH_PROCESSOR_a_API_KEY | MORPH_PROCESSOR_a_API_KEY is required",
    "MORPH_PROCESSOR_a_MODEL | MORPH_PROCESSOR_a_MODEL is required",
    "MORPH_PROCESSOR_b_CONCURRENCY | MORPH_PROCESSOR_b_CONCURRENCY must be a positive integer (got '0')",
    "MORPH_PROCESSOR_c_TYPE | MORPH_PROCESSOR_c_TYPE must be one of openrouter, stub (got 'openai')",
  ].join("\n"));
});

test("Read Registry example 4: unknown keys, both reasoning levers, an id without TYPE", () => {
  const got = readRegistry({
    MORPH_PROCESSOR_e_TYPE: "stub", MORPH_PROCESSOR_e_ANSWERS_DIR: "/x", MORPH_PROCESSOR_e_REASONING_EFFORT: "low",
    MORPH_PROCESSOR_e_REASONING_MAX_TOKENS: "100", MORPH_PROCESSOR_e_FOO: "1", MORPH_PROCESSOR_x_y_TYPE: "stub",
  });
  expect(ids(got), "no config").toBe("");
  expect(lines(got.faults), "four faults in key order").toBe([
    "MORPH_PROCESSOR_e_FOO | MORPH_PROCESSOR_e_FOO is not a known key",
    "MORPH_PROCESSOR_e_REASONING_EFFORT | MORPH_PROCESSOR_e_REASONING_EFFORT conflicts with MORPH_PROCESSOR_e_REASONING_MAX_TOKENS: set one",
    "MORPH_PROCESSOR_x_TYPE | MORPH_PROCESSOR_x_TYPE is required",
    "MORPH_PROCESSOR_x_y_TYPE | MORPH_PROCESSOR_x_y_TYPE is not a known key",
  ].join("\n"));
});

test("§2.2 rows: every message of the table, one env each", () => {
  const one = (env: Record<string, string>): string => lines(readRegistry(env).faults);
  const S = { MORPH_PROCESSOR_s_TYPE: "stub", MORPH_PROCESSOR_s_ANSWERS_DIR: "/x" };
  expect(one({ MORPH_PROCESSOR_TYPE: "stub" }), "no id").toBe(
    "MORPH_PROCESSOR_TYPE | MORPH_PROCESSOR_TYPE does not name MORPH_PROCESSOR_<id>_<KEY> with an id of [A-Za-z0-9-]");
  expect(one({ "MORPH_PROCESSOR_a.b_TYPE": "stub" }), "a dot in the id").toBe(
    "MORPH_PROCESSOR_a.b_TYPE | MORPH_PROCESSOR_a.b_TYPE does not name MORPH_PROCESSOR_<id>_<KEY> with an id of [A-Za-z0-9-]");
  expect(one({ MORPH_PROCESSOR_s_TYPE: "stub" }), "stub without ANSWERS_DIR").toBe(
    "MORPH_PROCESSOR_s_ANSWERS_DIR | MORPH_PROCESSOR_s_ANSWERS_DIR is required");
  expect(one({ MORPH_PROCESSOR_o_TYPE: "openrouter", MORPH_PROCESSOR_o_MODEL: "m", MORPH_PROCESSOR_o_API_KEY: "k",
    MORPH_PROCESSOR_o_ANSWERS_DIR: "/x" }), "ANSWERS_DIR on openrouter").toBe(
    "MORPH_PROCESSOR_o_ANSWERS_DIR | MORPH_PROCESSOR_o_ANSWERS_DIR is only for TYPE stub");
  expect(one({ ...S, MORPH_PROCESSOR_s_ROUTE: "fast" }), "route").toBe(
    "MORPH_PROCESSOR_s_ROUTE | MORPH_PROCESSOR_s_ROUTE must be one of sync, batch (got 'fast')");
  expect(one({ ...S, MORPH_PROCESSOR_s_TIMEOUT_MS: "1.5" }), "timeout").toBe(
    "MORPH_PROCESSOR_s_TIMEOUT_MS | MORPH_PROCESSOR_s_TIMEOUT_MS must be a positive integer (got '1.5')");
  expect(one({ ...S, MORPH_PROCESSOR_s_MAX_RETRIES: "-1" }), "retries").toBe(
    "MORPH_PROCESSOR_s_MAX_RETRIES | MORPH_PROCESSOR_s_MAX_RETRIES must be a non-negative integer (got '-1')");
  expect(one({ ...S, MORPH_PROCESSOR_s_REASONING_MAX_TOKENS: "0" }), "reasoning tokens").toBe(
    "MORPH_PROCESSOR_s_REASONING_MAX_TOKENS | MORPH_PROCESSOR_s_REASONING_MAX_TOKENS must be a positive integer (got '0')");
  expect(one({ ...S, MORPH_PROCESSOR_s_REASONING_EFFORT: "max" }), "effort").toBe(
    "MORPH_PROCESSOR_s_REASONING_EFFORT | MORPH_PROCESSOR_s_REASONING_EFFORT must be one of low, medium, high (got 'max')");
  expect(one({ MORPH_PROCESSOR_q_TYPE: "  " }), "an empty value is absent").toBe(
    "MORPH_PROCESSOR_q_TYPE | MORPH_PROCESSOR_q_TYPE is required");
  expect(one({ MORPH_PROCESSOR_b_TYPE: "x", MORPH_PROCESSOR_C_TYPE: "x" }), "faults by code unit: C before b").toBe([
    "MORPH_PROCESSOR_C_TYPE | MORPH_PROCESSOR_C_TYPE must be one of openrouter, stub (got 'x')",
    "MORPH_PROCESSOR_b_TYPE | MORPH_PROCESSOR_b_TYPE must be one of openrouter, stub (got 'x')",
  ].join("\n"));
});

test("§2.2 rows: values, defaults and ordering of a valid registry", () => {
  const got = readRegistry({
    MORPH_PROCESSOR_a_TYPE: "stub", MORPH_PROCESSOR_a_ANSWERS_DIR: "/a", MORPH_PROCESSOR_a_ROUTE: "batch",
    MORPH_PROCESSOR_a_MAX_RETRIES: "0", MORPH_PROCESSOR_a_TIMEOUT_MS: "5000", MORPH_PROCESSOR_a_REASONING_EFFORT: "high",
    MORPH_PROCESSOR_a_PROVIDER_ORDER: " , ", MORPH_PROCESSOR_a_MODEL: "own",
    MORPH_PROCESSOR_B_TYPE: "openrouter", MORPH_PROCESSOR_B_MODEL: "m", MORPH_PROCESSOR_B_API_KEY: "k",
    MORPH_PROCESSOR_B_BASE_URL: "http://127.0.0.1:9/v1", OTHER: "x",
  });
  expect(lines(got.faults), "faults").toBe("");
  expect(ids(got), "sorted by id in code-unit order (B before a, never localeCompare)").toBe("B,a");
  const z = got.configs[1] as ProcessorConfig;
  expect(`${z.route} ${z.maxRetries} ${z.timeoutMs} ${z.model}`, "route, retries, timeout, model").toBe("batch 0 5000 own");
  expect(JSON.stringify(z.reasoning), "effort lever").toBe('{"effort":"high"}');
  expect(z.providerOrder === null, "a list of blanks is null").toBe(true);
  expect((got.configs[0] as ProcessorConfig).baseUrl, "BASE_URL as given").toBe("http://127.0.0.1:9/v1");
  expect(readRegistry({}).configs.length + readRegistry({}).faults.length, "empty env").toBe(0);
});
MORPH_PROBE_EOF
echo '== tsc'; node_modules/.bin/tsc --noEmit -p $P/tsconfig.card.json
echo '== eslint'; node_modules/.bin/eslint src/processor/types.ts src/processor/registry.ts
echo '== guard'; node $P/guard.mjs src src/processor/types.ts,src/processor/registry.ts
echo '== probe'; node_modules/.bin/vitest run --config $P/probe.config.mts --reporter=dot > $P/vt.log 2>&1 || { grep -E '^ FAIL |Error|AssertionError|^ +Tests |^ +Test Files |expected|received' $P/vt.log | head -80; exit 1; }
echo '== full'; node_modules/.bin/vitest run --passWithNoTests --reporter=dot > $P/vt.log 2>&1 || { grep -E '^ FAIL |Error|AssertionError|^ +Tests |^ +Test Files |expected|received' $P/vt.log | head -80; exit 1; }
echo '== frozen'; git diff --quiet HEAD -- contour.yaml morph-map.json docs decks tests/fixtures || { echo "changed outside the targets: $(git diff --name-only HEAD -- contour.yaml morph-map.json docs decks tests/fixtures | tr "\n" " ")"; exit 1; }
X=$(git ls-files --others --exclude-standard | grep -vxF -e src/processor/types.ts -e src/processor/registry.ts || true); [ -z "$X" ] || { echo "files left in the tree: $X"; exit 1; }
) > $L 2>&1; rc=$?; cat $L; exit $rc

D=/tmp/morph/assemble-request-p4; mkdir -p $D; S=$(date +%s)-$$; L=$D/acc-$S.log
cp src/processor/assemble.ts $D/0-$S.ts 2>/dev/null
(
 set -e
 export NO_COLOR=1 CI=1
P=$PWD/probe/assemble-request; rm -rf $P; mkdir -p $P; trap 'rm -rf $P' EXIT
cat > $P/guard.mjs <<'MORPH_GUARD_EOF'
// MorphV2 guard: the layer rules of docs/CONVENTIONS.md and the test-file rules, checked on
// the TypeScript syntax tree. Inlined into every acceptance by decks/tools/build.py.
//   node guard.mjs src [file,file,...]                   every .ts under src/, or only these
//   node guard.mjs helpers <file> <name,name,...>        the stub module: node:* only, exports
//   node guard.mjs tests <file> <min> <max> [lits.json]  one test file; lits = strings it must hold
